package com.nook.widgets.test;

import android.app.*;
import android.appwidget.*;
import android.content.*;
import android.graphics.*;
import android.net.Uri;
import android.os.*;
import android.provider.MediaStore;
import android.view.*;
import android.widget.*;
import com.nook.widgets.*;
import org.json.*;
import java.io.*;
import java.util.*;
import java.util.concurrent.atomic.AtomicReference;
import java.util.function.BiConsumer;

/** Native material, stock-catalog and bound-widget checks; no microphone capture. */
public final class StockSmoke {
    private final Instrumentation i;private final Context c;private final AppWidgetHost host;private final BiConsumer<Boolean,String> check;private final List<Integer> ids=new ArrayList<>();
    private StockSmoke(Instrumentation i,Context c,AppWidgetHost host,BiConsumer<Boolean,String> check){this.i=i;this.c=c;this.host=host;this.check=check;}
    public static void run(Instrumentation i,Context c,AppWidgetHost host,BiConsumer<Boolean,String> check)throws Exception{new StockSmoke(i,c,host,check).run();}
    private void main(Runnable task){AtomicReference<Throwable> error=new AtomicReference<>();i.runOnMainSync(()->{try{task.run();}catch(Throwable e){error.set(e);}});if(error.get()!=null)throw new AssertionError(error.get());i.waitForIdleSync();}
    private int bind(String kind,JSONObject config){int id=host.allocateAppWidgetId();ids.add(id);check.accept(AppWidgetManager.getInstance(c).bindAppWidgetIdIfAllowed(id,new ComponentName(c,Widgets.provider(kind))),"Stock provider binds: "+kind);Store.config(c,id,config);Widgets.update(c,id,kind);return id;}
    private View render(String kind,JSONObject config,boolean compact){View v=Widgets.render(c,-1,kind,config,compact,false).apply(c,new FrameLayout(c));int w=Ui.dp(c,320),h=Ui.dp(c,compact?182:250);v.measure(View.MeasureSpec.makeMeasureSpec(w,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(h,View.MeasureSpec.EXACTLY));v.layout(0,0,w,h);return v;}
    private void click(int id,int target){main(()->host.createView(c,id,AppWidgetManager.getInstance(c).getAppWidgetInfo(id)).findViewById(target).performClick());SystemClock.sleep(100);i.waitForIdleSync();}
    private static TextView text(View v,String exact){if(v instanceof TextView t&&exact.contentEquals(t.getText()))return t;if(v instanceof ViewGroup group)for(int n=0;n<group.getChildCount();n++){TextView found=text(group.getChildAt(n),exact);if(found!=null)return found;}return null;}
    private void run()throws Exception{
        Uri wallpaper=null;Activity activity=null;String feedKey=null,previousFeed=null;Store.Item note=null;
        try{
            check.accept(Widgets.KINDS.length==37&&Widgets.CATALOG.length==38,"Thirty-seven dedicated tool families plus Universal are registered");Set<String> names=new HashSet<>();JSONObject inventory=new JSONObject();
            for(String brand:new String[]{"Apple","macOS","Pixel","Samsung","Nothing"}){JSONArray families=new JSONArray();for(StockCatalog.Family family:StockCatalog.families(brand)){check.accept(!family.source().isBlank()&&!family.detail().isBlank(),"Every stock family declares its data source");JSONArray layouts=new JSONArray();for(StockCatalog.Preset preset:StockCatalog.presets(family)){JSONObject config=StockCatalog.configuration(preset);check.accept(names.add(preset.id())&&Widgets.provider(preset.family().kind())!=null&&config.optInt("preferredWidth")>=180,"Stock preset has a unique, addable native configuration");layouts.put(new JSONObject().put("id",preset.id()).put("layout",preset.layout()).put("size",preset.size()));}families.put(new JSONObject().put("family",family.title()).put("source",family.source()).put("detail",family.detail()).put("layouts",layouts));}inventory.put(brand,families);}
            File dir=new File(c.getFilesDir(),"screenshots");dir.mkdirs();try(FileOutputStream out=new FileOutputStream(new File(dir,"stock-catalog.json"))){out.write(inventory.toString(2).getBytes(java.nio.charset.StandardCharsets.UTF_8));}
            main(()->{for(String kind:Widgets.KINDS)for(int design=0;design<WidgetDesign.NAMES.length;design++)for(boolean compact:new boolean[]{false,true})try{JSONObject config=Widgets.defaults(kind);WidgetDesign.select(config,design);config.put("style",3).put("transparency",50);View v=render(kind,config,compact);check.accept(v.findViewById(com.nook.widgets.R.id.widget_settings)!=null,"Liquid Glass renders every native tool and design");TextView title=v.findViewById(com.nook.widgets.R.id.widget_title);check.accept(title.getAlpha()==1&&Color.alpha(title.getCurrentTextColor())==255,"Glass preserves fully opaque content");}catch(Exception e){throw new RuntimeException(kind+" design="+design,e);}});
            for(String kind:ExtraKinds.KEYS)bind(kind,Widgets.defaults(kind));
            main(()->{for(String kind:Widgets.KINDS)try{JSONObject hub=Widgets.defaults("universal");WidgetDesign.select(hub,2);hub.put("page",kind).put("style",3).put("transparency",65);View view=Widgets.render(c,-1,"universal",hub,true,false).apply(c,new FrameLayout(c));check.accept(view.findViewById(com.nook.widgets.R.id.hub_next).getVisibility()==View.VISIBLE,"Liquid Glass Universal retains navigation for "+kind);check.accept(UniversalWidget.viewConfig(hub,kind).optInt("style")==3,"Universal shares glass with each module");}catch(Exception e){throw new RuntimeException(e);}});
            JSONObject sw=Widgets.defaults("stopwatch");int stopwatch=bind("stopwatch",sw);click(stopwatch,com.nook.widgets.R.id.widget_action0);check.accept(Store.config(c,stopwatch).optBoolean("running"),"Bound stopwatch starts through its real action");SystemClock.sleep(160);click(stopwatch,com.nook.widgets.R.id.widget_action0);check.accept(!Store.config(c,stopwatch).optBoolean("running",true)&&Store.config(c,stopwatch).optLong("elapsed")>=100,"Stopwatch pauses and saves actual monotonic elapsed time");click(stopwatch,com.nook.widgets.R.id.widget_action1);check.accept(Store.config(c,stopwatch).optJSONArray("laps").length()==1,"Stopwatch records a real lap");click(stopwatch,com.nook.widgets.R.id.widget_action2);check.accept(Store.config(c,stopwatch).optLong("elapsed")==0&&!Store.config(c,stopwatch).optBoolean("running"),"Stopwatch reset clears the session");
            JSONObject tracker=Widgets.defaults("tracker");tracker.put("trackerType","water").put("increment",250);int water=bind("tracker",tracker);click(water,com.nook.widgets.R.id.widget_action2);check.accept(Store.config(c,water).optInt("amount0")==250,"Bound manual tracker increments and persists");click(water,com.nook.widgets.R.id.widget_action0);check.accept(Store.config(c,water).optInt("amount0")==0,"Manual tracker decrement respects zero");JSONObject past=new JSONObject().put("amount0",750).put("daily",true).put("trackedDay","2000-01-01");check.accept(ExtraData.trackerValue(past,0)==0,"Daily logs do not display yesterday's value");
            JSONObject service=Widgets.defaults("service");service.put("serviceName","Find My");main(()->{View v=render("service",service,false);check.accept(text(v,"Manual card · no private account data")!=null,"Private-service templates do not impersonate live account data");});
            JSONObject parsed=FeedData.parseFeed("<rss><channel><item><title>Sample headline</title><link>https://example.com/story</link></item></channel></rss>");check.accept(parsed.getJSONArray("items").length()==1,"RSS parser reads source headlines and links");boolean rejected=false;try{FeedData.parseFeed("<!DOCTYPE rss SYSTEM 'file:///private'><rss/>");}catch(Exception e){rejected=true;}check.accept(rejected,"Feed reader rejects external document declarations");
            ContentValues values=new ContentValues();values.put(MediaStore.Images.Media.DISPLAY_NAME,"nook-glass-test.png");values.put(MediaStore.Images.Media.MIME_TYPE,"image/png");values.put(MediaStore.Images.Media.RELATIVE_PATH,"Pictures/Nook tests");wallpaper=c.getContentResolver().insert(MediaStore.Images.Media.EXTERNAL_CONTENT_URI,values);check.accept(wallpaper!=null,"A scoped wallpaper test image is created");Bitmap image=wallpaper();try(OutputStream out=c.getContentResolver().openOutputStream(wallpaper)){image.compress(Bitmap.CompressFormat.PNG,100,out);}image.recycle();String source=wallpaper.toString();
            main(()->{try{JSONObject plain=Widgets.defaults("notes");WidgetDesign.select(plain,2);plain.put("style",3).put("glassUri",source).put("glassBlur",0).put("glassRefraction",0);Bitmap sharp=GlassMaterial.render(c,plain,320,220,false);plain.put("glassBlur",20).put("glassRefraction",85);Bitmap optical=GlassMaterial.render(c,plain,320,220,false);int changed=0;for(int y=30;y<sharp.getHeight()-30;y+=7)for(int x=30;x<sharp.getWidth()-30;x+=7)if(sharp.getPixel(x,y)!=optical.getPixel(x,y))changed++;check.accept(changed>200,"Chosen wallpaper is actually blurred/refracted, rather than only tinted");sharp.recycle();optical.recycle();for(String kind:new String[]{"clock","weather","calendar","battery","stopwatch"}){JSONObject config=Widgets.defaults(kind);WidgetDesign.select(config,2);config.put("style",3);WidgetDesign.Colors colors=WidgetDesign.colors(config,kind);check.accept(colors.text==colors.accent&&colors.monochrome,"Clear glass has monochrome content across Apple tools");}for(int percent:new int[]{0,25,50,75,100}){plain.put("transparency",percent);View v=render("notes",plain,false);check.accept(((ImageView)v.findViewById(com.nook.widgets.R.id.widget_surface)).getImageAlpha()==Math.round(255*(100-percent)/100f),"Liquid Glass transparency retains exact percentage behavior");}}catch(Exception e){throw new RuntimeException(e);}});
            note=new Store.Item();note.title="Weekend plans";note.body="Book the train.\nPack the camera.";Store.save(c,"notes",note);JSONObject headlineConfig=Widgets.defaults("news");headlineConfig.put("feedUrl","https://example.com/nook-test.xml").put("feedName","Sample feed");feedKey=FeedData.key("news",headlineConfig);previousFeed=c.getSharedPreferences("nook_feeds",0).getString(feedKey,null);c.getSharedPreferences("nook_feeds",0).edit().putString(feedKey,parsed.toString()).commit();
            JSONObject files=Widgets.defaults("files");files.put("file0",source);int fileId=bind("files",files);AtomicReference<Intent> outgoing=new AtomicReference<>();Instrumentation.ActivityMonitor monitor=new Instrumentation.ActivityMonitor(){@Override public Instrumentation.ActivityResult onStartActivity(Intent intent){if(Intent.ACTION_VIEW.equals(intent.getAction())){outgoing.set(intent);return new Instrumentation.ActivityResult(Activity.RESULT_OK,null);}return null;}};i.addMonitor(monitor);try{click(fileId,com.nook.widgets.R.id.widget_row0);long until=SystemClock.elapsedRealtime()+5000;while(outgoing.get()==null&&SystemClock.elapsedRealtime()<until)SystemClock.sleep(50);check.accept(outgoing.get()!=null&&source.equals(outgoing.get().getDataString())&&(outgoing.get().getFlags()&Intent.FLAG_GRANT_READ_URI_PERMISSION)!=0,"Selected file opens its actual scoped URI with a read grant");}finally{i.removeMonitor(monitor);}
            activity=i.startActivitySync(new Intent(c,StockLibraryActivity.class).putExtra("brand","Apple").putExtra("liquid",true).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));i.waitForIdleSync();Activity display=activity;String noteId=note.id;main(()->board(display,source,noteId,headlineConfig));
            check.accept(StockCatalog.families("Apple").size()>18&&StockCatalog.families("Nothing").size()>11,"Brand libraries enumerate distinct named families beyond the original shared toolbox");
        }finally{if(activity!=null){Activity done=activity;main(done::finish);}for(int id:ids){host.deleteAppWidgetId(id);Store.removeConfig(c,id);}if(wallpaper!=null)c.getContentResolver().delete(wallpaper,null,null);if(note!=null)Store.delete(c,"notes",note.id);if(feedKey!=null){android.content.SharedPreferences.Editor edit=c.getSharedPreferences("nook_feeds",0).edit();if(previousFeed==null)edit.remove(feedKey);else edit.putString(feedKey,previousFeed);edit.commit();}}
    }
    private Bitmap wallpaper(){Bitmap b=Bitmap.createBitmap(760,1100,Bitmap.Config.ARGB_8888);Canvas canvas=new Canvas(b);Paint p=new Paint(3);p.setShader(new LinearGradient(0,0,760,1100,new int[]{0xff103d62,0xff5b2f85,0xffdc856c},null,Shader.TileMode.CLAMP));canvas.drawRect(0,0,760,1100,p);p.setShader(null);p.setColor(0xff59c4c4);canvas.drawOval(-300,70,500,480,p);p.setColor(0xffdcaf75);canvas.drawOval(390,500,1100,1260,p);p.setColor(0x80ffffff);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(5);for(int y=0;y<1100;y+=90)canvas.drawLine(0,y,760,y+220,p);return b;}
    private void board(Activity a,String wallpaperUri,String noteId,JSONObject news){
        try{String[] kinds={"notes","clock","calendar","battery","stopwatch","news"};Bitmap b=Bitmap.createBitmap(1600,2200,Bitmap.Config.ARGB_8888);Canvas canvas=new Canvas(b);Bitmap backdrop=wallpaper();canvas.drawBitmap(backdrop,null,new RectF(0,0,1600,2200),new Paint(3));backdrop.recycle();Paint text=new Paint(3);text.setColor(Color.WHITE);text.setTextSize(36);text.setTypeface(Typeface.create("sans-serif-medium",0));canvas.drawText("Apple-inspired · Liquid Glass",36,58,text);text.setTextSize(21);canvas.drawText("Native widgets · Wallpaper optics · Sample note and headlines; real clock, date and phone battery",36,96,text);ViewGroup parent=a.findViewById(android.R.id.content);
            for(int n=0;n<kinds.length;n++){String kind=kinds[n];JSONObject config=new JSONObject((kind.equals("news")?news:Widgets.defaults(kind)).toString());WidgetDesign.select(config,2);config.put("style",3).put("glassUri",wallpaperUri).put("glassZoom",215).put("glassCropX",n%2==0?5:95).put("glassCropY",12+n/2*34).put("_width",280).put("_height",220);if(kind.equals("notes"))config.put("entity",noteId);FrameLayout frame=new FrameLayout(c);View v=Widgets.render(c,-1,kind,config,false,true).apply(c,frame);frame.addView(v,new FrameLayout.LayoutParams(-1,-1));parent.addView(frame,new ViewGroup.LayoutParams(Ui.dp(c,280),Ui.dp(c,220)));int w=Ui.dp(c,280),h=Ui.dp(c,220);frame.measure(View.MeasureSpec.makeMeasureSpec(w,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(h,View.MeasureSpec.EXACTLY));frame.layout(0,0,w,h);int x=36+n%2*790,y=144+n/2*660;text.setTextSize(23);canvas.drawText(Widgets.title(kind),x,y-12,text);canvas.save();canvas.translate(x,y);canvas.scale(740f/w,582f/h);frame.draw(canvas);canvas.restore();parent.removeView(frame);}File dir=new File(c.getFilesDir(),"screenshots");dir.mkdirs();try(FileOutputStream out=new FileOutputStream(new File(dir,"liquid-glass.png"))){b.compress(Bitmap.CompressFormat.PNG,100,out);}b.recycle();
        }catch(Exception e){throw new RuntimeException(e);}
    }
}
